class PosnBitArray:
    def __init__(self, size: int):
        self.size = size
        self.arr = [0] * size

    def __getitem__(self, item):
        return self.arr[item]

    def __setitem__(self, key, value):
        self.arr[key] = value

    def __contains__(self, item):
        return self.arr[item] == 1

    def __iter__(self):
        return iter(self.arr)

    def __len__(self):
        return len(self.arr)

    def doc_encoded_posns(self, term_idx, doc_id=0):
        return [(doc_id, pos) for pos in self.arr[term_idx]]


class Terms:
    def __init__(self, tfs: dict, posns: Optional[dict] = None,
                 doc_len: int = 0, encoded=False):
        self.tfs = tfs
        self.posns = posns
        self.doc_len = doc_len
        self.encoded = encoded

    def __getitem__(self, key):
        return self.tfs[key]

    def __len__(self):
        return len(self.tfs)

    def __iter__(self):
        return iter(self.tfs.items())

    def __contains__(self, key):
        return key in self.tfs

    def __repr__(self):
        return repr(self.tfs)

    def __str__(self):
        return str(self.tfs)

    def __eq__(self, other):
        if not isinstance(other, Terms):
            return False
        return self.tfs == other.tfs

    def __lt__(self, other):
        if not isinstance(other, Terms):
            return False
        return self.tfs < other.

